### 1. Cargador de Entorno (`env.cjs`)
Módulo encargado de resolver las prioridades de configuración `.env.local` sobre `.env` con tipado estricto y validación de variables críticas para el ecosistema multi-tenant.

```javascript
// env.cjs
const fs = require('fs');
const path = require('path');

function loadEnv() {
  const rootDir = process.cwd();
  const envFiles = ['.env.local', '.env'];

  for (const file of envFiles) {
    const filePath = path.join(rootDir, file);
    if (fs.existsSync(filePath)) {
      const content = fs.readFileSync(filePath, 'utf8');
      const lines = content.split('\n');
      for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed && !trimmed.startsWith('#')) {
          const equalIndex = trimmed.indexOf('=');
          if (equalIndex > -1) {
            const key = trimmed.slice(0, equalIndex).trim();
            let value = trimmed.slice(equalIndex + 1).trim();
            // Remover comillas envolventes si existen
            if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
              value = value.slice(1, -1);
            }
            if (process.env[key] === undefined) {
              process.env[key] = value;
            }
          }
        }
      }
    }
  }

  // Validaciones críticas del sistema
  const requiredVars = ['SUPABASE_URL', 'SUPABASE_SERVICE_ROLE_KEY', 'EVOLUTION_API_KEY', 'WEBHOOK_SECRET'];
  for (const v of requiredVars) {
    if (!process.env[v]) {
      console.error(`[FATAL] Variable de entorno requerida no definida: ${v}`);
      process.exit(1);
    }
  }
}

loadEnv();

module.exports = {
  SUPABASE_URL: process.env.SUPABASE_URL,
  SUPABASE_SERVICE_ROLE_KEY: process.env.SUPABASE_SERVICE_ROLE_KEY,
  EVOLUTION_API_KEY: process.env.EVOLUTION_API_KEY,
  EVOLUTION_API_URL: process.env.EVOLUTION_API_URL || 'https://api.evolution.com',
  WEBHOOK_SECRET: process.env.WEBHOOK_SECRET,
  PORT: process.env.PORT ? parseInt(process.env.PORT, 10) : 3000
};
```

