### 2. Adaptador Evolution API v1/v2 & Servidor de Webhooks (`webhook-server.cjs`)
Servidor HTTP optimizado con soporte para `messages.upsert`, envío seguro mediante `sendText`, validación de API Key con prevención de ataques de temporización (`crypto.timingSafeEqual`) y fallback de firma HMAC para Meta/WhatsApp Business.

```javascript
// webhook-server.cjs
const http = require('http');
const crypto = require('crypto');
const { createClient } = require('@supabase/supabase-js');
const { SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, EVOLUTION_API_KEY, EVOLUTION_API_URL, WEBHOOK_SECRET, PORT } = require('./env.cjs');

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
  auth: { persistSession: false }
});

// Validador temporal seguro contra ataques de sincronización
function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) {
    // Aún ejecutamos timingSafeEqual con un buffer dummy para evitar timing leaks de longitud
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

// Adaptador de envío para Evolution API v1 / v2
async function sendText(instance, remoteJid, text) {
  const isV2 = EVOLUTION_API_URL.includes('/v2');
  const endpoint = isV2 
    ? `${EVOLUTION_API_URL}/instance/${instance}/message/send-text`
    : `${EVOLUTION_API_URL}/message/sendText/${instance}`;

  const payload = isV2 
    ? { number: remoteJid, text } 
    : { remoteJid, text, options: { delay: 1200, presence: 'composing' } };

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': EVOLUTION_API_KEY
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Evolution API Error [${response.status}]: ${errText}`);
  }

  return await response.json();
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/webhook') {
    let bodyChunks = [];

    req.on('data', chunk => bodyChunks.push(chunk));
    req.on('end', async () => {
      const rawBody = Buffer.concat(bodyChunks);
      const signatureHeader = req.headers['x-hub-signature-256'] || '';
      const apiKeyHeader = req.headers['apikey'] || req.headers['x-api-key'] || '';

      // 1. Validar Autenticación (Prioridad APIKey con timingSafeEqual, fallback HMAC Meta)
      let isAuthenticated = false;
      if (apiKeyHeader && safeCompare(apiKeyHeader, EVOLUTION_API_KEY)) {
        isAuthenticated = true;
      } else if (signatureHeader.startsWith('sha256=')) {
        const expectedSignature = 'sha256=' + crypto.createHmac('sha256', WEBHOOK_SECRET).update(rawBody).digest('hex');
        if (safeCompare(signatureHeader, expectedSignature)) {
          isAuthenticated = true;
        }
      }

      if (!isAuthenticated) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: Invalid credentials or signature' }));
        return;
      }

      try {
        const payload = JSON.parse(rawBody.toString('utf8'));
        const eventType = payload.event || payload.type;

        // Procesamiento de mensajes entrantes (messages.upsert)
        if (eventType === 'messages.upsert' || eventType === 'message') {
          const messageData = payload.data || payload;
          const remoteJid = messageData.key?.remoteJid || messageData.from;
          const messageContent = messageData.message?.conversation || messageData.message?.extendedTextMessage?.text || '';
          const tenantId = messageData.tenantId || payload.tenantId; // Multi-tenant context

          if (tenantId && remoteJid && messageContent) {
            // Persistencia transaccional en Supabase con aislamiento RLS vía RPC o cliente service_role con contexto
            const { error: dbError } = await supabase
              .from('crm_mensajes')
              .insert({
                tenant_id: tenantId,
                remote_jid: remoteJid,
                contenido: messageContent,
                direccion: 'entrante',
                raw_payload: payload
              });

            if (dbError) {
              console.error('[DB Error] Fallo al insertar mensaje:', dbError.message);
            }
          }
        }

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'success', processed: true }));
      } catch (err) {
        console.error('[Webhook Error]', err.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON payload' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not Found' }));
  }
});

server.listen(PORT, () => {
  console.log(`[Webhook Server] Escuchando en puerto ${PORT}`);
});

module.exports = { sendText, server };
