### 3. Worker Background Daemon (`worker.cjs`)
Daemon enfocado en la validación continua y sincronización de esquemas, inventario ABC y ejecución de pruebas de integridad transaccional (`DAEMON_SDD_DRY_RUN`).

```javascript
// worker.cjs
const { createClient } = require('@supabase/supabase-js');
const { SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY } = require('./env.cjs');

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
  auth: { persistSession: false }
});

const INTERVAL_MS = process.env.DAEMON_INTERVAL_MS ? parseInt(process.env.DAEMON_INTERVAL_MS, 10) : 30000;
const isDryRun = process.env.DAEMON_SDD_DRY_RUN === 'true';

async function executeDaemonCycle() {
  console.log(`[DAEMON] Iniciando ciclo de sincronización. DRY_RUN: ${isDryRun}`);

  try {
    // 1. Auditoría de consistencia de inventario ABC
    const { data: abcData, error: abcError } = await supabase.rpc('auditar_consistencia_inventario_abc');
    if (abcError) {
      console.error('[DAEMON ERROR] Fallo en auditoría ABC:', abcError.message);
    } else {
      console.log('[DAEMON] Auditoría ABC completada:', abcData);
    }

    // 2. Procesamiento de cola de notificaciones pendientes
    const { data: queue, error: qError } = await supabase
      .from('notificaciones_cola')
      .select('*')
      .eq('estado', 'pendiente')
      .limit(50);

    if (qError) {
      console.error('[DAEMON ERROR] Fallo al leer cola de notificaciones:', qError.message);
    } else if (queue && queue.length > 0) {
      for (const item of queue) {
        console.log(`[DAEMON] Procesando notificación ID: ${item.id} para tenant: ${item.tenant_id}`);
        if (!isDryRun) {
          // Marcar como procesado en modo real
          await supabase
            .from('notificaciones_cola')
            .update({ estado: 'enviado', actualizado_en: new Date().toISOString() })
            .eq('id', item.id);
        }
      }
    }
  } catch (err) {
    console.error('[DAEMON FATAL] Error crítico en ciclo del worker:', err);
  }
}

function startDaemon() {
  console.log(`[DAEMON] Worker iniciado con intervalo de ${INTERVAL_MS}ms`);
  setInterval(executeDaemonCycle, INTERVAL_MS);
}

if (require.main === module) {
  startDaemon();
}

module.exports = { executeDaemonCycle, startDaemon };
```

