### 4. Harness de Pruebas y Auditoría Estática (`audit-runner.cjs`)
Script automatizado para validación estática de tipos con `tsc` configurado con un tiempo de espera estricto de **90,000ms** (90 segundos) y ejecución de pruebas unitarias/integración.

```javascript
// audit-runner.cjs
const { exec } = require('child_process');
const path = require('path');

const TSC_TIMEOUT_MS = 90000; // 90 segundos estrictos

function runAudit() {
  console.log('[AUDIT RUNNER] Iniciando compilación y verificación estática con tsc...');
  const startTime = Date.now();

  const tscProcess = exec('npx tsc --noEmit', {
    timeout: TSC_TIMEOUT_MS,
    maxBuffer: 1024 * 1024 * 10
  }, (error, stdout, stderr) => {
    const duration = Date.now() - startTime;

    if (error) {
      console.error(`[AUDIT FAIL] Falló la verificación de TypeScript tras ${duration}ms`);
      if (error.killed) {
        console.error(`[AUDIT TIMEOUT] El proceso excedió el límite de ${TSC_TIMEOUT_MS}ms`);
      }
      if (stdout) console.stdout(stdout);
      if (stderr) console.error(stderr);
      process.exit(1);
    }

    console.log(`[AUDIT SUCCESS] Verificación estática completada exitosamente en ${duration}ms`);
    if (stdout) console.log(stdout);

    // Ejecutar pruebas adicionales si aplica
    runUnitTests();
  });
}

function runUnitTests() {
  console.log('[AUDIT RUNNER] Ejecutando suite de pruebas unitarias...');
  const testProcess = exec('node --test', { timeout: 30000 }, (error, stdout, stderr) => {
    if (error) {
      console.error('[AUDIT FAIL] Fallaron las pruebas unitarias');
      console.error(stderr);
      process.exit(1);
    }
    console.log('[AUDIT SUCCESS] Todas las pruebas pasaron correctamente');
    console.log(stdout);
    process.exit(0);
  });
}

if (require.main === module) {
  runAudit();
}

module.exports = { runAudit };
```

